import { readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const audioDir = join(process.cwd(), 'public', 'audio');
const manifestPath = join(process.cwd(), 'src', 'data', 'audioManifest.ts');

let keys = [];
try {
  keys = readdirSync(audioDir)
    .filter((file) => file.toLowerCase().endsWith('.mp3'))
    .map((file) => file.replace(/\.mp3$/i, ''))
    .sort((a, b) => a.localeCompare(b, 'en'));
} catch {
  keys = [];
}

const content = `// ============================================================
// Auto-generated by scripts/sync-audio-manifest.mjs.
// Put fixed narration MP3 files in /public/audio using names like:
//   slide-01.mp3, slide-02.mp3, ...
// Files listed here are used before browser TTS, so the voice stays identical
// across PC, iPhone, Android, and every browser.
// ============================================================

export const AUDIO_MANIFEST: string[] = ${JSON.stringify(keys, null, 2)};

export function hasAudio(key: string): boolean {
  return AUDIO_MANIFEST.includes(key);
}
`;

writeFileSync(manifestPath, content);
console.log(`Audio manifest synced: ${keys.length} MP3 file(s).`);
